// CommDSP-Bench: cmul anchor task — naive baseline
//
// 朴素实现：4 个并行乘法器 + 加减法，单拍组合数据通路。
// 该文件是进化的初始程序，EVOLVE-BLOCK 标记内的代码可被改写。

module top (
    input  wire               clk,
    input  wire               rst_n,
    input  wire               in_valid,
    output wire               in_ready,
    input  wire signed [15:0] a,
    input  wire signed [15:0] b,
    input  wire signed [15:0] c,
    input  wire signed [15:0] d,
    output reg                out_valid,
    input  wire               out_ready,
    output reg  signed [32:0] y_re,
    output reg  signed [32:0] y_im
);

    // EVOLVE-BLOCK-START
    // 3-mult complex multiply (Karatsuba/Gauss):
    //   p1=a*c, p2=b*d, p3=(a+b)*(c+d)
    //   y_re = p1 - p2 ;  y_im = p3 - p1 - p2   (== a*d + b*c)
    assign in_ready = 1'b1;

    wire signed [16:0] ab = a + b;
    wire signed [16:0] cd = c + d;
    wire signed [33:0] p3 = ab  * cd;
    wire signed [32:0] p1 = a   * c;
    wire signed [32:0] p2 = b   * d;

    always @(posedge clk) begin
        if (!rst_n) begin
            out_valid <= 1'b0;
            y_re      <= 33'sd0;
            y_im      <= 33'sd0;
        end else if (in_valid && in_ready) begin
            y_re      <= p1 - p2;
            y_im      <= p3 - p1 - p2;
            out_valid <= 1'b1;
        end else if (out_valid && out_ready) begin
            out_valid <= 1'b0;
        end
    end
    // EVOLVE-BLOCK-END

endmodule

